<script setup>
import { computed, nextTick, ref } from 'vue'
import Search from 'lucide-vue-next/dist/esm/icons/search.js'
import MapPin from 'lucide-vue-next/dist/esm/icons/map-pin.js'
import Map from 'lucide-vue-next/dist/esm/icons/map.js'
import Grid2X2 from 'lucide-vue-next/dist/esm/icons/grid-2x2.js'
import Castle from 'lucide-vue-next/dist/esm/icons/castle.js'
import Utensils from 'lucide-vue-next/dist/esm/icons/utensils.js'
import Waves from 'lucide-vue-next/dist/esm/icons/waves.js'
import Trees from 'lucide-vue-next/dist/esm/icons/trees.js'
import Landmark from 'lucide-vue-next/dist/esm/icons/landmark.js'
import Bed from 'lucide-vue-next/dist/esm/icons/bed.js'
import Heart from 'lucide-vue-next/dist/esm/icons/heart.js'
import ArrowUpRight from 'lucide-vue-next/dist/esm/icons/arrow-up-right.js'
import ArrowRight from 'lucide-vue-next/dist/esm/icons/arrow-right.js'
import LocateFixed from 'lucide-vue-next/dist/esm/icons/locate-fixed.js'
import SlidersHorizontal from 'lucide-vue-next/dist/esm/icons/sliders-horizontal.js'
import X from 'lucide-vue-next/dist/esm/icons/x.js'
import Route from 'lucide-vue-next/dist/esm/icons/route.js'
import TravelMap from './TravelMap.vue'
import { placeFacets, filterPlaces, matchesRegion } from '../explore.js'
import { useGeolocation } from '../useGeolocation.js'
const props=defineProps({places:{type:Array,required:true},favorites:{type:Array,default:()=>[]}})
const emit=defineEmits(['open','favorite','planner'])
const region=ref('Lubuskie'),query=ref(''),chosen=ref([]),tab=ref('places'),sort=ref('recommended'),filtersOpen=ref(false)
const icons={castle:Castle,utensils:Utensils,waves:Waves,trees:Trees,landmark:Landmark,bed:Bed}
const {position:userLocation,loading:locating,error:locationError,locate}=useGeolocation()
const base=computed(()=>filterPlaces(props.places,region.value,query.value,[]))
const results=computed(()=>{const found=filterPlaces(props.places,region.value,query.value,chosen.value);return sort.value==='name'?[...found].sort((a,b)=>a.name.localeCompare(b.name,'pl')):found})
const activeFacets=computed(()=>placeFacets.filter(f=>chosen.value.includes(f.id)))
const tabs=[{id:'places',name:'Miejsca',icon:Grid2X2},{id:'map',name:'Mapa',icon:Map}]
function reset(){region.value='Lubuskie';query.value='';chosen.value=[]}
function removeFacet(id){chosen.value=chosen.value.filter(x=>x!==id)}
function openMarker(id){const place=results.value.find(p=>p.id===id);if(place)emit('open',place)}
function switchTab(event,index){let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();const container=event.currentTarget.parentElement;tab.value=tabs[next].id;nextTick(()=>container.querySelectorAll('[role="tab"]')[next]?.focus())}
</script>

<template>
 <main class="explore-home">
  <div class="explore-top"><div><div class="section-kicker">PERŁY ZIEMI LUBUSKIEJ</div><h1>Odkrywaj po swojemu<span>.</span></h1><p>Wybierz to, co Cię ciekawi. Znajdź miejsce na kolejną przygodę.</p></div><button class="button explore-planner" @click="emit('planner')"><Route :size="17"/>Zaplanuj wycieczkę<ArrowUpRight :size="16"/></button></div>
  <button class="mobile-filter-toggle" :aria-expanded="filtersOpen" aria-controls="explore-filters" @click="filtersOpen=!filtersOpen"><SlidersHorizontal :size="17"/>Region i filtry<span v-if="chosen.length">{{chosen.length}}</span></button>
  <div class="explore-layout">
   <aside id="explore-filters" :class="['explore-sidebar',{expanded:filtersOpen}]" aria-label="Filtry miejsc">
    <div class="sidebar-heading"><h2>Znajdź swój kierunek</h2><SlidersHorizontal :size="17"/></div>
    <label class="filter-label" for="explore-region">Jaki region?</label><div class="region-input"><MapPin :size="18"/><input id="explore-region" v-model="region" list="explore-regions" placeholder="Wpisz region" autocomplete="off"><datalist id="explore-regions"><option value="Lubuskie"/></datalist></div>
    <div class="region-note"><span></span>Odkrywamy województwo lubuskie</div>
    <label class="filter-label query-label" for="explore-query">Szukasz konkretnego miejsca?</label><div class="explore-search"><Search :size="17"/><input id="explore-query" v-model="query" placeholder="Nazwa lub miejscowość…" type="search"></div>
    <fieldset class="facet-list"><legend>Czego szukasz?</legend><p>Wybierz jedną lub kilka kategorii.</p><label v-for="facet in placeFacets" :key="facet.id" :class="['facet-option',{checked:chosen.includes(facet.id)}]"><input type="checkbox" v-model="chosen" :value="facet.id"><component :is="icons[facet.icon]" :size="18"/><span>{{facet.name}}</span><small>{{base.filter(facet.match).length}}</small></label></fieldset>
    <button class="clear-explore-filters" @click="reset"><X :size="14"/>Wyczyść filtry</button>
    <div class="sidebar-region-image"><img src="/images/lake.webp" alt="Zielone brzegi jeziora w Lubuskiem"><span>Blisko natury.<br>Bliżej przygody.</span></div>
   </aside>
   <section class="explore-results" aria-label="Wyniki wyszukiwania">
    <div class="explore-result-top"><div><h2>{{matchesRegion(region)?'Twoje miejsca w Lubuskiem':'Znajdź swój region'}}</h2><p role="status">Znalezione miejsca: <strong>{{results.length}}</strong></p></div><label v-if="tab==='places'" class="explore-sort">Sortuj<select v-model="sort" aria-label="Sortuj miejsca"><option value="recommended">Polecane</option><option value="name">Nazwa A–Z</option></select></label></div>
    <div class="explore-view-bar"><div class="explore-tabs" role="tablist" aria-label="Sposób wyświetlania miejsc"><button v-for="(item,index) in tabs" :key="item.id" :id="`explore-tab-${item.id}`" role="tab" :aria-selected="tab===item.id" :aria-controls="`explore-panel-${item.id}`" :tabindex="tab===item.id?0:-1" :class="{active:tab===item.id}" @click="tab=item.id" @keydown="switchTab($event,index)"><component :is="item.icon" :size="17"/>{{item.name}}<span v-if="item.id==='places'">{{results.length}}</span></button></div><button v-if="tab==='map'" class="locate-button" :disabled="locating" @click="locate"><LocateFixed :size="17"/>{{locating?'Ustalam lokalizację…':userLocation?'Odśwież moją lokalizację':'Pokaż, gdzie jestem'}}</button></div>
    <div v-if="activeFacets.length" class="explore-chips" aria-label="Aktywne filtry"><button v-for="facet in activeFacets" :key="facet.id" @click="removeFacet(facet.id)" :aria-label="`Usuń filtr: ${facet.name}`">{{facet.name}}<X :size="12"/></button></div>
    <section v-if="tab==='places'" id="explore-panel-places" role="tabpanel" aria-labelledby="explore-tab-places">
     <div v-if="results.length" class="explore-grid"><article v-for="place in results" :key="place.id" class="place-card explore-place"><button class="place-image" @click="emit('open',place)"><img :src="place.image" :alt="place.name" loading="lazy"><span class="place-tag">{{place.category==='food'?'Inspiracja kulinarna':place.category==='nature'?'Przyroda':'Zabytki i historia'}}</span></button><button :class="['heart-btn',{liked:favorites.includes(place.id)}]" :aria-label="`${favorites.includes(place.id)?'Usuń z ulubionych':'Dodaj do ulubionych'}: ${place.name}`" :aria-pressed="favorites.includes(place.id)" @click="emit('favorite',place.id)"><Heart :size="19" :fill="favorites.includes(place.id)?'currentColor':'none'"/></button><div class="place-info"><span class="place-location"><MapPin :size="12"/>{{place.location}}</span><button class="place-title" @click="emit('open',place)">{{place.name}}</button><p>{{place.subtitle}}</p><button class="card-arrow" :aria-label="`Zobacz ${place.name}`" @click="emit('open',place)"><ArrowUpRight :size="20"/></button></div></article></div>
     <div v-else class="explore-empty"><Search :size="34"/><h3>{{!region.trim()?'Od jakiego regionu zaczynamy?':!matchesRegion(region)?'Ten region jeszcze na nas czeka':'Nie znaleźliśmy takich miejsc'}}</h3><p>{{!matchesRegion(region)?'Wpisz Lubuskie, aby odkryć miejsca z naszego katalogu.':'Zmień kategorie lub wyszukiwaną nazwę. Możesz też wyczyścić filtry i zobaczyć wszystkie miejsca.'}}</p><button class="button outline" @click="reset">Pokaż miejsca w Lubuskiem<ArrowRight :size="16"/></button></div>
    </section>
    <section v-else id="explore-panel-map" role="tabpanel" aria-labelledby="explore-tab-map">
     <p v-if="locationError" class="location-error" role="alert">{{locationError}}</p>
     <div class="explore-map"><TravelMap :places="results" :user-location="userLocation" fit-places @select="openMarker"/><div class="explore-map-caption"><MapPin :size="14"/>Miejsca na mapie: {{results.length}}</div><div v-if="!results.length" class="map-no-results">Brak miejsc dla tych filtrów. Zmień wybór po lewej.</div></div>
     <div class="explore-map-legend"><span><i class="place-dot"></i>Miejsca z Twoich filtrów</span><span v-if="userLocation"><i class="user-dot"></i>Tu jesteś <small v-if="userLocation.accuracy!==null">(dokładność ok. {{Math.round(userLocation.accuracy)}} m)</small></span><span v-else>Użyj „Pokaż, gdzie jestem”, aby zaznaczyć swoją pozycję.</span></div>
    </section>
   </section>
  </div>
 </main>
</template>

